ues above 90th percentile become 90th percentile\nwinsorized = []\nfor v in nasa_billions:\n    if v < p10:\n        winsorized.append(p10)\n    elif v > p90:\n        winsorized.append(p90)\n    else:\n        winsorized.append(v)\n\nprint(f\"\\nWinsorized values: {winsorized}\")\n\n# Calculate range\nwinsorized_range = max(winsorized) - min(winsorized)\nprint(f\"\\n10% Winsorized Range: {winsorized_range:.2f} billion\")\n\n# Alternative: using scipy if available\ntry:\n    from scipy.stats import mstats\n    winsorized_scipy = mstats.winsorize(nasa_billions, limits=[0.1, 0.1])\n    range_scipy = max(winsorized_scipy) - min(winsorized_scipy)\n    print(f\"\\nScipy winsorized range: {range_scipy:.2f}\")\nexcept Exception as e:\n    print(f\"Error with scipy: {e}\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
